import Templates from 'core/templates';
import {call as ajaxCall} from 'core/ajax';
import Notification from 'core/notification';
import {THEMES, ICONS, esc, normaliseIcon, iconToSpan, openPicker, closePicker} from './infographic_shared';
import {getContextId} from '../context';
import {defaultText} from './default_texts';
import {alignVars, bindAlign, normalizeAlign} from './block_align';
import {bindWidth, normalizeWidth, widthVars} from './block_width';
import {MAX_STEPS, normalizeCurrent, stepState} from './step_state';

// HTML renderers — vertical (default) and horizontal.
// ---------------------------------------------------------------------------

/**
 * @param {object} item Step item.
 * @param {number} stepNum 1-based step number.
 * @param {object} c Theme palette.
 * @param {string} state The state of the step: 'done', 'current', 'next' or ''.
 * @returns {string}
 */
const badgeHtml = (item, stepNum, c, state = '') => {
    const iconClass = item.icon ? normaliseIcon(item.icon) : '';
    let content = iconClass
        ? iconToSpan(iconClass)
        : `<span aria-hidden="true">${stepNum}</span>`;
    // A step that is over shows a tick where its number or icon was.
    if (state === 'done') {
        content = '<span aria-hidden="true">&#10003;</span>';
    }
    return `<div class="slms-steps__badge" style="background:${c.iconBg};color:${c.iconColor};">${content}</div>`;
};

/**
 * The words that say a step is over or is the current one: the stylesheet shows it too, but the cleaner of a forum or
 * a question removes the names an assistive technology would read, so the state is also in visible text.
 *
 * @param {string} state The state of the step.
 * @param {object} c Theme palette.
 * @returns {string}
 */
const stateHtml = (state, c) => {
    const text = {done: defaultText('steps_state_done'), current: defaultText('steps_state_current')}[state];
    return text ? `<div class="slms-steps__state" style="color:${c.valuColor};">${esc(text)}</div>` : '';
};

/**
 * The line under the title of a step, when it has one.
 *
 * @param {object} item Step item.
 * @param {object} c Theme palette.
 * @returns {string}
 */
const descriptionHtml = (item, c) => (item.description
    ? `<div class="slms-steps__step-desc" style="color:${c.labelColor};">${esc(item.description)}</div>`
    : '');

/**
 * The class that gives a step its state, with the space that goes before it.
 *
 * @param {string} state The state of the step.
 * @returns {string}
 */
const stateClass = (state) => (state ? ` slms-steps-state-${state}` : '');

/**
 * The steps of a block, as the ones that have a title.
 *
 * @param {object} data Block data.
 * @returns {object[]}
 */
const stepsOf = (data) => (Array.isArray(data.items) ? data.items.filter((item) => item.title) : []);

/**
 * The heading above the steps, when the block has one.
 *
 * @param {object} data Block data.
 * @param {object} c Theme palette.
 * @returns {string}
 */
const headingHtml = (data, c) => (data.title && data.title.trim()
    ? `<div class="slms-steps__title" style="color:${c.titleColor};">${esc(data.title.trim())}</div>`
    : '');

/**
 * Builds the inner HTML for the vertical steps layout.
 * @param {object} data Block data.
 * @param {object} c Theme colour palette.
 * @returns {string}
 */
const buildVerticalHtml = (data, c) => {
    const items = stepsOf(data);
    if (!items.length) {
        return '';
    }
    const current = normalizeCurrent(data.current, items.length);
    const steps = items.map((item, idx) => {
        const isLast = idx === items.length - 1;
        const state = stepState(idx + 1, current);
        const connector = isLast ? '' : `<div class="slms-steps__connector" style="background:${c.borderColor};"></div>`;
        return [
            `<div class="slms-steps__item${stateClass(state)}">`,
            `<div class="slms-steps__left">${badgeHtml(item, idx + 1, c, state)}${connector}</div>`,
            `<div class="slms-steps__content" style="padding-bottom:${isLast ? '0' : '1.25rem'};">`,
            `<div class="slms-steps__step-title" style="color:${c.valuColor};">${esc(item.title)}</div>`,
            descriptionHtml(item, c),
            stateHtml(state, c),
            '</div>',
            '</div>',
        ].join('');
    });
    return [headingHtml(data, c), '<div class="slms-steps__list">', ...steps, '</div>'].join('');
};

/**
 * Builds the inner HTML for the horizontal steps layout.
 * @param {object} data Block data.
 * @param {object} c Theme colour palette.
 * @returns {string}
 */
const buildHorizontalHtml = (data, c) => {
    const items = stepsOf(data);
    if (!items.length) {
        return '';
    }
    const current = normalizeCurrent(data.current, items.length);
    const steps = items.map((item, idx) => {
        const state = stepState(idx + 1, current);
        const connector = idx === items.length - 1
            ? ''
            : `<div class="slms-steps__hconnector" style="background:${c.borderColor};"></div>`;
        return [
            `<div class="slms-steps__item--h${stateClass(state)}">`,
            badgeHtml(item, idx + 1, c, state),
            `<div class="slms-steps__step-title--h" style="color:${c.valuColor};">${esc(item.title)}</div>`,
            descriptionHtml(item, c),
            stateHtml(state, c),
            '</div>',
            connector,
        ].join('');
    });
    return [headingHtml(data, c), '<div class="slms-steps__list--h">', ...steps, '</div>'].join('');
};

// ---------------------------------------------------------------------------
// Popup data helpers.
// ---------------------------------------------------------------------------

/**
 * @param {object} data
 * @returns {object}
 */
const dataToPopupVars = (data) => {
    const items = Array.isArray(data.items) ? data.items : [];
    const out = {
        title: data.title || '',
        themeBlue: (data.theme || 'blue') === 'blue',
        themeGreen: data.theme === 'green',
        themePurple: data.theme === 'purple',
        themeOrange: data.theme === 'orange',
        themeRed: data.theme === 'red',
        themeBlack: data.theme === 'black',
        layoutVertical: (data.layout || 'vertical') === 'vertical',
        layoutHorizontal: data.layout === 'horizontal',
    };
    // Which option of the current step is selected; a value that does not fit the steps marks none.
    const current = normalizeCurrent(data.current, MAX_STEPS);
    for (let i = 0; i <= MAX_STEPS; i++) {
        out[`current${i}`] = current === i;
    }
    for (let i = 0; i < 6; i++) {
        const item = items[i] || {};
        out[`item${i + 1}_icon`] = item.icon || '';
        out[`item${i + 1}_title`] = item.title || '';
        out[`item${i + 1}_description`] = item.description || '';
        out[`item${i + 1}_stepnum`] = i + 1;
        out[`item${i + 1}_hasicon`] = !!(item.icon);
    }
    return out;
};

/**
 * @param {Element} popup
 * @param {object} data
 */
const readItemsFromPopup = (popup, data) => {
    const items = [];
    for (let i = 1; i <= 6; i++) {
        const icon = popup.querySelector(`#st_item${i}_icon`)?.value?.trim() || '';
        const title = popup.querySelector(`#st_item${i}_title`)?.value?.trim() || '';
        const description = popup.querySelector(`#st_item${i}_description`)?.value?.trim() || '';
        if (title) {
            items.push({icon, title, description});
        }
    }
    data.items = items.length ? items : [{icon: '', title: defaultText('default_step_title', 1), description: ''}];
};

// ---------------------------------------------------------------------------
// Block export.
// ---------------------------------------------------------------------------

export default {
    id: 'infographicSteps',
    titleString: 'block_infographic_steps_title',
    icon: '🪜',

    defaultData: {
        align: 'center',
        width: 'reduced',
        title: '',
        theme: 'blue',
        layout: 'vertical',
        // Number of the step the class is at (1 to 6), or 0 for none: the steps before it show as done.
        current: 0,
        items: [
            {icon: '', title: '', description: ''},
            {icon: '', title: '', description: ''},
            {icon: '', title: '', description: ''},
        ],
    },

    buildToolbar: async(container, data, onUpdate, PopupManager) => {
        try {
            const {html, js} = await Templates.renderForPromise('tiny_studiolms/toolbar_infographic_steps', {});
            Templates.replaceNodeContents(container, html, js);

            const btnEdit = container.querySelector('#tb-infographic-steps-edit');
            if (!btnEdit) {
                return;
            }

            btnEdit.addEventListener('click', () => {
                closePicker();

                const tplData = dataToPopupVars(data);
                Object.assign(tplData, alignVars(data.align, 'center'));
                Object.assign(tplData, widthVars(data.width, 'reduced'));

                PopupManager.open(btnEdit, 'tiny_studiolms/popup_infographic_steps_edit', tplData, (popup) => {
                    bindAlign(popup, data, onUpdate);
                    bindWidth(popup, data, onUpdate);
                    const titleEl = popup.querySelector('#st_title');
                    const themeButtons = popup.querySelectorAll('.slms-ig-theme-btn');
                    const aiBtnEl = popup.querySelector('#st-ai-btn');
                    const aiPromptEl = popup.querySelector('#st_ai_prompt');
                    const aiSpinner = popup.querySelector('#st-ai-spinner');
                    const aiError = popup.querySelector('#st-ai-error');

                    const applyChanges = () => {
                        if (titleEl) {
                            data.title = titleEl.value.trim();
                        }
                        readItemsFromPopup(popup, data);
                        onUpdate(data);
                    };

                    if (titleEl) {
                        titleEl.addEventListener('input', applyChanges);
                    }

                    for (let i = 1; i <= 6; i++) {
                        ['title', 'description'].forEach(field => {
                            popup.querySelector(`#st_item${i}_${field}`)
                                ?.addEventListener('input', applyChanges);
                        });
                    }

                    // Icon picker buttons.
                    for (let i = 1; i <= 6; i++) {
                        const iconBtn = popup.querySelector(`.slms-st-icon-btn[data-item="${i}"]`);
                        const iconInput = popup.querySelector(`#st_item${i}_icon`);
                        if (iconBtn && iconInput) {
                            iconBtn.addEventListener('click', (e) => {
                                e.stopPropagation();
                                openPicker(iconBtn, (cls) => {
                                    iconInput.value = cls;
                                    iconBtn.innerHTML = `<i class="${cls}" aria-hidden="true"></i>`;
                                    applyChanges();
                                }, ICONS);
                            });
                        }
                    }

                    // Theme picker.
                    themeButtons.forEach(btn => {
                        btn.addEventListener('click', () => {
                            themeButtons.forEach(b => b.classList.remove('selected'));
                            btn.classList.add('selected');
                            data.theme = btn.getAttribute('data-theme') || 'blue';
                            onUpdate(data);
                        });
                    });

                    // Current step.
                    popup.querySelector('#st_current')?.addEventListener('input', (ev) => {
                        data.current = normalizeCurrent(ev.target.value, MAX_STEPS);
                        onUpdate(data);
                    });

                    // Layout picker.
                    const layoutButtons = popup.querySelectorAll('.slms-st-layout-btn');
                    layoutButtons.forEach(btn => {
                        btn.addEventListener('click', () => {
                            layoutButtons.forEach(b => b.classList.remove('selected'));
                            btn.classList.add('selected');
                            data.layout = btn.getAttribute('data-layout') || 'vertical';
                            onUpdate(data);
                        });
                    });

                    // AI generation.
                    if (aiBtnEl && aiPromptEl) {
                        aiBtnEl.addEventListener('click', async() => {
                            const prompt = aiPromptEl.value.trim();
                            if (!prompt) {
                                return;
                            }
                            aiBtnEl.disabled = true;
                            aiSpinner?.classList.remove('d-none');
                            if (aiError) {
                                aiError.textContent = '';
                                aiError.classList.add('d-none');
                            }

                            try {
                                const [promise] = ajaxCall([{
                                    methodname: 'tiny_studiolms_generate_infographic_steps',
                                    args: {topic: prompt, contextid: getContextId()},
                                }]);
                                const result = await promise;

                                data.title = result.title || '';
                                data.items = JSON.parse(result.items || '[]');

                                if (titleEl) {
                                    titleEl.value = data.title;
                                }
                                const newVars = dataToPopupVars(data);
                                for (let i = 1; i <= 6; i++) {
                                    const iconInput = popup.querySelector(`#st_item${i}_icon`);
                                    const iconBtn = popup.querySelector(`.slms-st-icon-btn[data-item="${i}"]`);
                                    const titleInput = popup.querySelector(`#st_item${i}_title`);
                                    const descInput = popup.querySelector(`#st_item${i}_description`);
                                    const iconVal = newVars[`item${i}_icon`] || '';
                                    if (iconInput) {
                                        iconInput.value = iconVal;
                                    }
                                    if (iconBtn) {
                                        // The value comes straight from the LLM response: escape it
                                        // so a quote cannot break out of the class attribute.
                                        iconBtn.innerHTML = iconVal
                                            ? `<i class="${esc(iconVal)}" aria-hidden="true"></i>`
                                            : `<span aria-hidden="true">${i}</span>`;
                                    }
                                    if (titleInput) {
                                        titleInput.value = newVars[`item${i}_title`] || '';
                                    }
                                    if (descInput) {
                                        descInput.value = newVars[`item${i}_description`] || '';
                                    }
                                }
                                onUpdate(data);
                            } catch (err) {
                                if (aiError) {
                                    // The err.message is already the translated moodle_exception text the server
                                    // sent (infographic_steps_ai_error) — no need to fetch it again client-side.
                                    aiError.textContent = err.message;
                                    aiError.classList.remove('d-none');
                                }
                            } finally {
                                aiBtnEl.disabled = false;
                                aiSpinner?.classList.add('d-none');
                            }
                        });
                    }
                });
            });
        } catch (error) {
            // A genuinely unexpected failure (a template/DOM error, not an anticipated business
            // rule), so it goes through Notification.exception() instead of inline text —
            // reserved for real bugs, not routine validation failures.
            container.innerHTML = '';
            Notification.exception(error);
        }
    },

    renderHtml: async(data) => {
        const theme = data.theme || 'blue';
        const palette = THEMES[theme] || THEMES.blue;
        const layout = data.layout || 'vertical';
        const content = layout === 'horizontal'
            ? buildHorizontalHtml(data, palette)
            : buildVerticalHtml(data, palette);

        return Templates.render('tiny_studiolms/block_infographic_steps', {
            hoverEffect: data.hoverEffect,
            align: normalizeAlign(data.align, 'center'),
            width: normalizeWidth(data.width, 'reduced'),
            theme,
            layout,
            content,
        });
    },
};
